<?php
require_once __DIR__.'/helpers.php';
require_once __DIR__.'/erp_migrations.php';
require_once __DIR__.'/app/Services/ProductLabelService.php';
require_once __DIR__.'/app/Services/Code128Barcode.php';
require_login();gt_erp_run_phase1_migrations($pdo);
$user=current_user($pdo)?:[];$profile=(string)($user['access_profile']??'Utilizador');
if((int)($user['is_admin']??0)!==1&&!in_array($profile,['Utilizador','Produção','Chefias','RH'],true)){http_response_code(403);exit('Sem acesso às etiquetas de produto.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!validate_csrf_or_abort(false)){http_response_code(400);exit('Pedido de impressão inválido.');}
$orderId=filter_var($_POST['production_order_id']??null,FILTER_VALIDATE_INT);$operationId=filter_var($_POST['operation_id']??null,FILTER_VALIDATE_INT);
if(!$orderId||!$operationId){http_response_code(422);exit('A OF e a operação são obrigatórias.');}
$service=new ProductLabelService($pdo);
try{$data=$service->data((int)$orderId,(int)$operationId);$values=$service->validatePrint($_POST);$barcode=Code128Barcode::svg((string)$data['lot']);}
catch(InvalidArgumentException $e){http_response_code(422);exit(h($e->getMessage()));}
catch(RuntimeException $e){http_response_code(403);exit(h($e->getMessage()));}
$autoPrint=($_POST['mode']??'preview')==='print';if($autoPrint)$service->audit($data,$values,(int)$user['id']);
$logo=trim((string)app_setting($pdo,'logo_report_dark',''));if($logo==='')$logo=trim((string)app_setting($pdo,'logo_navbar_light',''));
$company=trim((string)app_setting($pdo,'company_name','TISSER'))?:'TISSER';
function product_label_number($number):string{return number_format((float)$number,fmod((float)$number,1.0)===0.0?0:2,',',' ');}
?><!doctype html><html lang="pt"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Etiqueta de produto · <?=h((string)$data['order_number'])?></title><style>
