</style></head><body><div class="print-toolbar"><button type="button" class="secondary" onclick="window.close()">Fechar</button><button type="button" onclick="window.print()">Imprimir <?=count(range(1,$values['copies']))?> etiqueta<?= $values['copies']===1?'':'s' ?></button></div><main class="labels"><?php for($copy=1;$copy<=$values['copies'];$copy++):?><article class="product-label"><header class="label-head"><div class="brand"><?php if($logo!==''):?><img src="<?=h($logo)?>" alt="<?=h($company)?>"><?php else:?><span class="brand-fallback"><?=h($company)?></span><?php endif;?></div><div class="date"><span class="eyebrow">Data</span><strong><?=$values['date']->format('d/m/Y')?></strong></div></header><section class="customer"><span class="eyebrow">Cliente</span><strong><?=h((string)$data['customer_name'])?></strong><span><?=h((string)$data['locality'])?></span></section><section class="product"><span class="eyebrow">Produto</span><div class="product-code"><?=h((string)$data['product_code'])?></div><div class="description"><?=h((string)$data['product_description'])?></div></section><section class="key-grid"><div class="key-box"><span class="eyebrow">Quantidade</span><strong><?=h(product_label_number($values['quantity']))?></strong></div><div class="key-box"><span class="eyebrow">Lote</span><strong><?=h((string)$data['lot'])?></strong></div></section><div class="barcode"><?=$barcode?><strong><?=h((string)$data['lot'])?></strong></div><footer class="label-foot"><span><?=h($company)?> · Thinking Packaging</span><span>OF <?=h((string)$data['order_number'])?></span></footer></article><?php endfor;?></main><?php if($autoPrint):?><script>window.addEventListener('load',function(){window.print();});</script><?php endif;?></body></html>
